async function tgPost(method, body) {
  try {
    return await this.helpers.httpRequest({ method: 'POST', url: `${BASE_URL}/${method}`, body, json: true });
  } catch (err) {
    if (body && body.parse_mode) {
      delete body.parse_mode;
      try {
        return await this.helpers.httpRequest({ method: 'POST', url: `${BASE_URL}/${method}`, body, json: true });
      } catch (e) {}
    }
    throw err;
  }
}

async function sendMessage(chatId, text, replyMarkup) {
  const body = { chat_id: chatId, text, parse_mode: 'HTML' };
  if (businessConnectionId) {
    body.business_connection_id = businessConnectionId;
  } else if (replyMarkup) {
    body.reply_markup = replyMarkup;
  }
  if (messageThreadId) body.message_thread_id = messageThreadId;
  await tgPost.call(this, 'sendMessage', body);
}

