const ADMIN_NOTIFICATION_IDS = [5437246207, 6576926570, 5660757898];

const guestDirectLink = (username && username !== '-')
  ? ('<a href="https://t.me/' + username.replace('@', '') + '">' + username + '</a> • <a href="tg://user?id=' + fromId + '">Buka Chat Langsung</a>')
  : ('<a href="tg://user?id=' + fromId + '">Buka Chat Tamu</a>');

// =========================================================================
// 1. DETEKSI PERTANYAAN ANEH / ESKALASI KE MRS. AFNY
// =========================================================================
const escalateMatch = aiOutput.match(/\[ESCALATE_QUESTION:\s*([^\]]+)\]/i);
const isEscalate = Boolean(escalateMatch) || aiOutput.toLowerCase().includes('diteruskan oleh mrs. afny') || aiOutput.toLowerCase().includes('dijawab langsung oleh mrs. afny') || rawInputText.includes('narkoba') || rawInputText.includes('senjata') || rawInputText.includes('diskon') || rawInputText.includes('nego') || rawInputText.includes('komplain');

if (isEscalate) {
  const reason = escalateMatch ? escalateMatch[1].trim() : 'Pertanyaan di luar SOP / Butuh respon Mrs. Afny';
  aiOutput = aiOutput.replace(/\[ESCALATE_QUESTION:[^\]]*\]/gi, '').trim();

  const alertMsg = '⚠️ <b>PERTANYAAN KHUSUS / BUTUH TAKEOVER MRS. AFNY!</b>\n\n' +
    '👤 <b>Nama Tamu:</b> <a href="tg://user?id=' + fromId + '">' + senderName + '</a> (' + username + ')\n' +
    '🆔 <b>Telegram ID:</b> <code>' + fromId + '</code>\n' +
    '💬 <b>Isi Pertanyaan Tamu:</b> "' + (parseData.text || '') + '"\n' +
    '📌 <b>Ringkasan:</b> ' + reason + '\n' +
    '⏰ <b>Waktu:</b> ' + dateWib + ' WIB\n\n' +
    '👉 <b>Chat Tamu Langsung:</b> ' + guestDirectLink;

  for (const adminId of ADMIN_NOTIFICATION_IDS) {
    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: `${BASE_URL}/sendMessage`,
        body: { chat_id: adminId, text: alertMsg, parse_mode: 'HTML' },
        json: true
      });
    } catch (e) {}
  }
}

// =========================================================================
// 2. DETEKSI RESERVASI / BOOKING LENGKAP
// =========================================================================
const bookingLeadMatch = aiOutput.match(/\[BOOKING_LEAD:\s*([^\]]+)\]/i);
const isBookingLead = Boolean(bookingLeadMatch) || aiOutput.includes('[NEED_ADMIN]') || rawInputText.includes('booking') || rawInputText.includes('reservasi') || rawInputText.includes('pesan room');

if (isBookingLead) {
  const bookingDetail = bookingLeadMatch ? bookingLeadMatch[1].trim() : 'Permintaan reservasi dari percakapan AI';
  aiOutput = aiOutput.replace(/\[BOOKING_LEAD:[^\]]*\]/gi, '').replace('[NEED_ADMIN]', '').trim();

  const leadMsg = '🔔 <b>PERMINTAAN RESERVASI / BOOKING BARU!</b>\n\n' +
    '👤 <b>Nama Tamu:</b> <a href="tg://user?id=' + fromId + '">' + senderName + '</a> (' + username + ')\n' +
    '🆔 <b>Telegram ID:</b> <code>' + fromId + '</code>\n' +
    '🏢 <b>Detail Reservasi:</b> ' + bookingDetail + '\n' +
    '💬 <b>Pesan Terakhir Tamu:</b> "' + (parseData.text || '') + '"\n' +
    '⏰ <b>Waktu:</b> ' + dateWib + ' WIB\n\n' +
    '👉 <b>Chat Tamu Langsung:</b> ' + guestDirectLink;

  for (const adminId of ADMIN_NOTIFICATION_IDS) {
    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: `${BASE_URL}/sendMessage`,
        body: { chat_id: adminId, text: leadMsg, parse_mode: 'HTML' },
        json: true
      });
    } catch (e) {}
  }
}

// Bersihkan sisa tag jika ada
aiOutput = aiOutput.replace(/\[ESCALATE_QUESTION:[^\]]*\]/gi, '').replace(/\[BOOKING_LEAD:[^\]]*\]/gi, '').replace('[NEED_ADMIN]', '').trim();

const imageUrlMatch = aiOutput.match(/https?:\/\/[^\s\)"]+\.(jpg|jpeg|png)/i);

// Helper pengiriman pesan dengan 3-Level Fallback Anti-Gagal
async function sendRawText(textToSend) {
  const body = { chat_id: chatId, text: textToSend };
  if (businessConnectionId) body.business_connection_id = businessConnectionId;
  if (messageThreadId) body.message_thread_id = messageThreadId;

  // Level 1: Coba kirim HTML
  try {
    body.parse_mode = 'HTML';
    return await this.helpers.httpRequest({ method: 'POST', url: `${BASE_URL}/sendMessage`, body, json: true });
  } catch (err) {
    // Level 2: Coba kirim Plain Text bersih tanpa tag
    delete body.parse_mode;
    body.text = textToSend.replace(/<[^>]+>/g, '').replace(/&amp;/g, '&');
    try {
      return await this.helpers.httpRequest({ method: 'POST', url: `${BASE_URL}/sendMessage`, body, json: true });
    } catch (e) {
      console.error('Final fallback sendMessage error:', e);
    }
  }
}

if (imageUrlMatch) {
  const imageUrl = imageUrlMatch[0];
  let cleanText = aiOutput.replace(imageUrl, '').replace(/<https?:[^>]+>/g, '').trim();

  let photoSent = false;
  const photoBody = { chat_id: chatId, photo: imageUrl };
  if (businessConnectionId) photoBody.business_connection_id = businessConnectionId;
  if (messageThreadId) photoBody.message_thread_id = messageThreadId;
  if (cleanText && cleanText.length <= 1024) {
    photoBody.caption = cleanText;
    photoBody.parse_mode = 'HTML';
  }

  try {
    await this.helpers.httpRequest({ method: 'POST', url: `${BASE_URL}/sendPhoto`, body: photoBody, json: true });
    photoSent = true;
  } catch (e) {
    console.log('sendPhoto failed, falling back to sendMessage...');
  }

  if (photoSent && cleanText.length > 1024) {
    await sendRawText.call(this, cleanText);
  } else if (!photoSent) {
    // Jika foto gagal, kirimkan seluruh teksnya tanpa gagal!
    await sendRawText.call(this, cleanText || aiOutput);
  }
} else {
  await sendRawText.call(this, aiOutput);
}

return { done: true };
